func Test_ResourceGuard_Spec_WhenPropertiesConverted_RoundTripsWithoutLoss(t *testing.T) {
	t.Parallel()

	if testing.Short() {
		return
	}

	parameters := gopter.DefaultTestParameters()
	parameters.MaxSize = 10
	properties := gopter.NewProperties(parameters)
	properties.Property(
		"Round trip from ResourceGuard_Spec to ResourceGuard_Spec via AssignProperties_To_ResourceGuard_Spec & AssignProperties_From_ResourceGuard_Spec returns original",
		prop.ForAll(RunPropertyAssignmentTestForResourceGuard_Spec, ResourceGuard_SpecGenerator()))
	properties.TestingRun(t, gopter.NewFormatedReporter(false, 240, os.Stdout))
}

// RunPropertyAssignmentTestForResourceGuard_Spec tests if a specific instance of ResourceGuard_Spec can be assigned to storage and back losslessly
func RunPropertyAssignmentTestForResourceGuard_Spec(subject ResourceGuard_Spec) string {
	// Copy subject to make sure assignment doesn't modify it
	copied := subject.DeepCopy()

	// Use AssignPropertiesTo() for the first stage of conversion
	var other storage.ResourceGuard_Spec
	err := copied.AssignProperties_To_ResourceGuard_Spec(&other)
	if err != nil {
		return err.Error()
	}

	// Use AssignPropertiesFrom() to convert back to our original type
	var actual ResourceGuard_Spec
	err = actual.AssignProperties_From_ResourceGuard_Spec(&other)
	if err != nil {
		return err.Error()
	}

	// Check for a match
	match := cmp.Equal(subject, actual, cmpopts.EquateEmpty())
	if !match {
		actualFmt := pretty.Sprint(actual)
		subjectFmt := pretty.Sprint(subject)
		result := diff.Diff(subjectFmt, actualFmt)
		return result
	}

	return ""
}

