// RunJSONSerializationTestForResourceGuard_Spec runs a test to see if a specific instance of ResourceGuard_Spec round trips to JSON and back losslessly
func RunJSONSerializationTestForResourceGuard_Spec(subject ResourceGuard_Spec) string {
	// Serialize to JSON
	bin, err := json.Marshal(subject)
	if err != nil {
		return err.Error()
	}

	// Deserialize back into memory
	var actual ResourceGuard_Spec
	err = json.Unmarshal(bin, &actual)
	if err != nil {
		return err.Error()
	}

	// Check for outcome
	match := cmp.Equal(subject, actual, cmpopts.EquateEmpty())
	if !match {
		actualFmt := pretty.Sprint(actual)
		subjectFmt := pretty.Sprint(subject)
		result := diff.Diff(subjectFmt, actualFmt)
		return result
	}

	return ""
}

// Generator of ResourceGuard_Spec instances for property testing - lazily instantiated by ResourceGuard_SpecGenerator()
var resourceGuard_SpecGenerator gopter.Gen

// ResourceGuard_SpecGenerator returns a generator of ResourceGuard_Spec instances for property testing.
// We first initialize resourceGuard_SpecGenerator with a simplified generator based on the
// fields with primitive types then replacing it with a more complex one that also handles complex fields
// to ensure any cycles in the object graph properly terminate.
func ResourceGuard_SpecGenerator() gopter.Gen {
	if resourceGuard_SpecGenerator != nil {
		return resourceGuard_SpecGenerator
	}

	generators := make(map[string]gopter.Gen)
	AddIndependentPropertyGeneratorsForResourceGuard_Spec(generators)
	resourceGuard_SpecGenerator = gen.Struct(reflect.TypeOf(ResourceGuard_Spec{}), generators)

	// The above call to gen.Struct() captures the map, so create a new one
	generators = make(map[string]gopter.Gen)
	AddIndependentPropertyGeneratorsForResourceGuard_Spec(generators)
	AddRelatedPropertyGeneratorsForResourceGuard_Spec(generators)
	resourceGuard_SpecGenerator = gen.Struct(reflect.TypeOf(ResourceGuard_Spec{}), generators)

	return resourceGuard_SpecGenerator
}

